class Solution:
    def minNonZeroProduct(self, p: int) -> int:
        n = (1 << p) - 1
        budget = [sum((v >> k) & 1 for v in range(1, n + 1)) for k in range(p)]
        cur = [0] * n
        best = float('inf')

        def rec(i):
            nonlocal best
            if i == n:
                if any(budget):
                    return
                prod = 1
                for v in cur:
                    prod *= v
                best = min(best, prod)
                return
            for x in range(1, n + 1):
                if all((x >> k) & 1 <= budget[k] for k in range(p)):
                    for k in range(p):
                        if x >> k & 1:
                            budget[k] -= 1
                    cur[i] = x
                    rec(i + 1)
                    for k in range(p):
                        if x >> k & 1:
                            budget[k] += 1
            cur[i] = 0

        rec(0)
        return best

