class Solution {
public:
    int minNonZeroProduct(int p) {
        int n = (1 << p) - 1;
        vector<int> budget(p), cur(n);
        for (int k = 0; k < p; k++)
            for (int v = 1; v <= n; v++) budget[k] += (v >> k) & 1;
        long long best = LLONG_MAX;
        function<void(int)> rec = [&](int i) {
            if (i == n) {
                for (int b : budget) if (b) return;
                long long prod = 1;
                for (int v : cur) prod *= v;
                best = min(best, prod);
                return;
            }
            for (int x = 1; x <= n; x++) {
                bool ok = true;
                for (int k = 0; k < p && ok; k++)
                    if (((x >> k) & 1) > budget[k]) ok = false;
                if (!ok) continue;
                for (int k = 0; k < p; k++)
                    if ((x >> k) & 1) budget[k]--;
                cur[i] = x;
                rec(i + 1);
                for (int k = 0; k < p; k++)
                    if ((x >> k) & 1) budget[k]++;
            }
            cur[i] = 0;
        };
        rec(0);
        return (int)best;
    }
};

