class Solution {
    public int minNonZeroProduct(int p) {
        int n = (1 << p) - 1;
        int[] budget = new int[p], cur = new int[n];
        for (int k = 0; k < p; k++)
            for (int v = 1; v <= n; v++) budget[k] += (v >> k) & 1;
        long[] best = {Long.MAX_VALUE};
        rec(0, n, p, budget, cur, best);
        return (int) best[0];
    }

    private void rec(int i, int n, int p, int[] budget, int[] cur, long[] best) {
        if (i == n) {
            for (int b : budget) if (b != 0) return;
            long prod = 1;
            for (int v : cur) prod *= v;
            best[0] = Math.min(best[0], prod);
            return;
        }
        for (int x = 1; x <= n; x++) {
            boolean ok = true;
            for (int k = 0; k < p && ok; k++)
                if (((x >> k) & 1) > budget[k]) ok = false;
            if (!ok) continue;
            for (int k = 0; k < p; k++)
                if ((x >> k & 1) == 1) budget[k]--;
            cur[i] = x;
            rec(i + 1, n, p, budget, cur, best);
            for (int k = 0; k < p; k++)
                if ((x >> k & 1) == 1) budget[k]++;
        }
        cur[i] = 0;
    }
}

