class Solution {
public:
    int minNonZeroProduct(int p) {
        const long long MOD = 1e9 + 7;
        long long top = (1LL << p) - 1;
        auto power = [&](long long b, long long e) {
            long long r = 1;
            b %= MOD;
            while (e > 0) {
                if (e & 1) r = r * b % MOD;
                b = b * b % MOD;
                e >>= 1;
            }
            return r;
        };
        return (int)(power(top - 1, top / 2) * (top % MOD) % MOD);
    }
};

