class Solution {
    public int minNonZeroProduct(int p) {
        final long MOD = (long) 1e9 + 7;
        long top = (1L << p) - 1;
        long base = (top - 1) % MOD;
        long exp = top / 2;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return (int) (result * (top % MOD) % MOD);
    }
}

